// @ts-check
/**
 * @fileoverview Teardown catalog — vendored facts-only snapshot
 * (`catalog/teardowns.json`).
 *
 * The catalog is the engine-side source of truth for a TD's facts (id, pillar,
 * severity, points, fixSummary, languages). It is regenerated by peek.software
 * from the frontend teardown catalog (see docs §5.2). In Phase 1 it is empty;
 * providers fall back to their own rule metadata until Phase 2 vends real data.
 */
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

/** @typedef {import('./types.mjs').Pillar} Pillar */
/** @typedef {import('./types.mjs').Severity} Severity */

/**
 * A single teardown fact entry (mirrors the snapshot format).
 * @typedef {Object} TeardownFact
 * @property {string} id — `TD-###`.
 * @property {Pillar} pillar — category → pillar (1:1).
 * @property {Severity} severity
 * @property {number | null} points — scan points (null until the snapshot carries them).
 * @property {string | null} fixSummary
 * @property {string | null} mappedQuestion — quiz-question back-link (Q#.#), null when none.
 * @property {string[]} languages — languages/frameworks with rule variants.
 */

/** Absolute path to the vendored catalog snapshot. */
const CATALOG_PATH = fileURLToPath(new URL('../catalog/teardowns.json', import.meta.url));

/** Lazily-built in-memory index (id → fact). */
/** @type {Map<string, TeardownFact> | null} */
let index = null;

/**
 * Load the catalog into an in-memory index (idempotent).
 * @returns {Promise<Map<string, TeardownFact>>}
 */
async function loadIndex() {
  if (index) return index;
  const raw = await readFile(CATALOG_PATH, 'utf8');
  const catalog = JSON.parse(raw);
  const list = /** @type {TeardownFact[]} */ (Array.isArray(catalog.teardowns) ? catalog.teardowns : []);
  index = new Map(list.map((fact) => [fact.id, fact]));
  return index;
}

/**
 * Look up a teardown fact by id.
 * @param {string} teardownId — e.g. "TD-008".
 * @returns {Promise<TeardownFact | undefined>} the fact, or undefined when absent.
 */
export async function lookupTeardown(teardownId) {
  const map = await loadIndex();
  return map.get(teardownId);
}

/**
 * Return every vendored teardown fact (for reverse-indexing, e.g. question→TD).
 * @returns {Promise<TeardownFact[]>}
 */
export async function listTeardowns() {
  const map = await loadIndex();
  return [...map.values()];
}
